"""The signed-in user's own notifications (generated by a database trigger)."""
import asyncio
import json

import jwt
from fastapi import APIRouter, Depends, HTTPException, Query, Request
from fastapi.responses import StreamingResponse
from starlette.concurrency import run_in_threadpool

from ..auth import User, current_user, load_user
from ..config import JWT_SECRET
from ..db import fetch_all, scalar, transaction
from ..realtime import hub

HEARTBEAT_S = 15

router = APIRouter(prefix="/api/notifications", tags=["notifications"])


@router.get("")
def list_notifications(limit: int = Query(30, ge=1, le=200), unread_only: bool = False,
                       user: User = Depends(current_user)):
    with transaction() as conn:
        rows = fetch_all(conn, f"""
            SELECT n.id, n.kind, n.title, n.message, n.release_id, n.created_at, n.read_at,
                   a.username AS actor
            FROM notifications n LEFT JOIN users a ON a.id = n.actor_id
            WHERE n.user_id = %s {"AND n.read_at IS NULL" if unread_only else ""}
            ORDER BY n.id DESC LIMIT %s""", (user.id, limit))
        unread = scalar(conn, "SELECT count(*) FROM notifications WHERE user_id = %s AND read_at IS NULL",
                        (user.id,))
    return {"notifications": rows, "unread": unread}


@router.get("/unread-count")
def unread_count(user: User = Depends(current_user)):
    """Cheap endpoint the UI polls; `latest_id` tells it whether anything new arrived."""
    with transaction() as conn:
        row = conn.execute("""SELECT count(*) FILTER (WHERE read_at IS NULL) AS unread,
                                     coalesce(max(id), 0) AS latest_id
                              FROM notifications WHERE user_id = %s""", (user.id,)).fetchone()
    return row


@router.post("/{notification_id}/read")
def mark_read(notification_id: int, user: User = Depends(current_user)):
    with transaction() as conn:
        if not scalar(conn, "SELECT mark_notification_read(%s, %s)", (notification_id, user.id)):
            # Either not yours, missing, or already read - report the first two as 404.
            exists = scalar(conn, "SELECT count(*) FROM notifications WHERE id = %s AND user_id = %s",
                            (notification_id, user.id))
            if not exists:
                raise HTTPException(404, "notification not found")
    return {"ok": True}


@router.post("/read-all")
def mark_all_read(user: User = Depends(current_user)):
    with transaction() as conn:
        n = scalar(conn, "SELECT mark_all_notifications_read(%s)", (user.id,))
    return {"marked": n}


@router.get("/stream")
async def stream(request: Request, token: str = Query(..., description="the same JWT used for the API")):
    """
    Server-Sent Events: one `notification` event per new notification for the
    signed-in user, pushed the moment the action that caused it commits.
    (EventSource cannot send headers, so the token comes as a query parameter.)
    """
    try:
        uid = int(jwt.decode(token, JWT_SECRET, algorithms=["HS256"])["sub"])
    except (jwt.PyJWTError, KeyError, ValueError) as e:
        raise HTTPException(401, "invalid token") from e
    if await run_in_threadpool(load_user, uid) is None:
        raise HTTPException(401, "account is not active")

    queue = hub.subscribe(uid)

    async def events():
        beats = 0
        try:
            yield "retry: 3000\nevent: ready\ndata: {}\n\n"
            while True:
                try:
                    nid = await asyncio.wait_for(queue.get(), timeout=HEARTBEAT_S)
                    yield f"event: notification\ndata: {json.dumps({'id': nid})}\n\n"
                except asyncio.TimeoutError:
                    beats += 1
                    if await request.is_disconnected():
                        break
                    # Every minute, make sure the account is still allowed in.
                    if beats % 4 == 0 and await run_in_threadpool(load_user, uid) is None:
                        yield "event: revoked\ndata: {}\n\n"
                        break
                    yield ": keep-alive\n\n"
        finally:
            hub.unsubscribe(uid, queue)

    return StreamingResponse(events(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no",
                                      "Connection": "keep-alive"})
